metrics.daxExpression:
CALCULATE(SUM(fact_project_cash_position_v[cost_to_date]),
fact_project_cash_position_v[etl_gold_timestamp] = MAX(fact_project_cash_position_v[etl_gold_timestamp])
)

CALCULATE(SUM(fact_project_cash_position_v[cash_paid_out]),
fact_project_cash_position_v[etl_gold_timestamp] = MAX(fact_project_cash_position_v[etl_gold_timestamp])
)

CALCULATE(SUM(fact_pcco_adjustments_v[amount]), 
    fact_pcco_adjustments_v[month_ending_date]=MAX(fact_pcco_adjustments_v[month_ending_date])
)

CALCULATE(max(fact_cost_vs_budget_summary_v[original_budget]), 
    FILTER(fact_cost_vs_budget_summary_v,
        fact_cost_vs_budget_summary_v[month_ending_date] = MAX(fact_cost_vs_budget_summary_v[month_ending_date])
    )
)

VAR Bottom4 =
    TOPN(
        4,
        FILTER(
            ALLSELECTED('Project Grades'[project_number]),
            CALCULATE([FIN_Score_Measure]) <> 0
        ),
        [FIN_Score_Measure],
        ASC,
        'Project Grades'[project_number],
        ASC
    )

VAR RankedTable =
    ADDCOLUMNS(
        Bottom4,
        "@Score", CALCULATE([FIN_Score_Measure]),
        "@Index",
            RANKX(
                Bottom4,
                CALCULATE([FIN_Score_Measure]),
                ,
                ASC,
                SKIP
            )
    )

RETURN
"<div style='border:none;
             padding:0;
             margin:0;
             width:100%;
             font-family:Segoe UI;'>"
&
CONCATENATEX(
    RankedTable,
    VAR Score = [@Score]

    VAR Color =
        SWITCH(
            TRUE(),
            Score < 0.5, "#EE8B8E",
            Score < 0.8, "#F3D03E",
            "#92E9A6"
        )

    VAR BorderStyle =
        IF(
            [@Index] = 4,
            "border-bottom:none;",
            "border-bottom:1px solid #E6E6E6;"
        )

    RETURN
        "<div style='display:flex;
                    justify-content:space-between;
                    align-items:center;
                    width:100%;
                    padding:4px 0;
                    margin:0;
                    " & BorderStyle & "
                    font-family:Segoe UI;
                    font-size:16px;
                    font-weight:700;'>

            <div style='margin-left:18px;
                        color:#333;'>" &
                'Project Grades'[project_number] &
            "</div>

            <div style='background-color:" & Color & ";
                        padding:1px 10px;
                        line-height:16px;
                        border-radius:4px;
                        color:#111;
                        text-align:center;
                        min-width:70px;
                        margin-right:18px;'>" &
                FORMAT(Score, "0.00%") &
            "</div>

        </div>",
    "",
    [@Score],
    ASC
)
&
"</div>"

